                              {prop.type && <span className="text-xs bg-coda-100 text-coda-700 px-1.5 py-0.5 rounded">{prop.type}</span>}
                            </div>
                            {prop.description && <p className="text-xs text-text-secondary mt-1">{prop.description}</p>}
