215→// Helper functions for parsing MCP responses and formatting data.
216→// Helpers MUST safely extract data from MCP JSON-RPC responses.
217→
218→/**
219→ * Extract parsed JSON from an MCP resource response.
220→// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers🛠️parsemcpresource](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers/d/i/parseMcpResource)
221→ *
222→ * MUST return null when the response has no valid content.
223→ **/
224→function parseMcpResource<T>(response: McpResponse): T | null {
225→  try {
226→    if (response.error) return null;
227→    const contents = response.result?.contents;
228→    if (contents && contents.length > 0 && contents[0].text) {
229→      return JSON.parse(contents[0].text) as T;
230→    }
231→    return null;
232→  } catch {
233→    return null;
234→  }
235→}
236→
237→/**
238→ * Extract parsed JSON from an MCP tool response.
239→// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers🛠️parsemcptool](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers/d/i/parseMcpTool)
240→ *
241→ * MUST return null when the response has no valid content.
242→ **/
243→function parseMcpTool<T>(response: McpResponse): T | null {
244→  try {
245→    if (response.error) return null;
246→    const content = response.result?.content;
247→    if (content && content.length > 0 && content[0].text) {
248→      return JSON.parse(content[0].text) as T;
249→    }
250→    return null;
251→  } catch {
252→    return null;
253→  }
254→}
