256→/**
257→ * Format a timestamp or ID string for display.
258→// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers🛠️formatid](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers/d/i/formatId)
259→ *
260→ * MUST return a human-readable string.
261→ **/
262→function formatId(id: string | undefined): string {
263→  if (!id) return "—";
264→  return id.replace(/_/g, " ").replace(/-/g, " ");
265→}
