1238→/**
1239→ * Actions page for invoking coda MCP tools.
1240→// [🔬coda🖱️desktop💻renderer🔖renderer🔖pages🔖actionspage🛠️actionspage](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Pages/s/ActionsPage/d/i/ActionsPage)
1241→ *
1242→ * MUST provide buttons for all coda tools and display results.
1243→ **/
1244→function ActionsPage({ refreshKey, onRefresh }: { refreshKey: number; onRefresh: () => void }) {
1245→  const { data: project } = useCodaResource<Project>("coda://project", refreshKey);
1246→  const targetIds = useMemo(() => project?.targets?.map((t) => t.id) ?? [], [project]);
1247→
1248→  const [actionLog, setActionLog] = useState<Array<{ id: number; action: string; result: unknown; timestamp: string; success: boolean }>>([]);
1249→  const [loading, setLoading] = useState<string | null>(null);
1250→
1251→  const runTool = useCallback(async (name: string, args: Record<string, unknown>, label: string) => {
