        )}

        {targets && targets.length > 0 && (
          <Card title={`Targets (${targets.length})`}>
            <div className="space-y-1">
              {targets.map((t) => (
                <div key={t.id} className="flex items-start gap-2 rounded px-2 py-1.5 text-sm hover:bg-surface-hover">
