function FixAction({ loading, onFix, disabled }: { loading: string | null; onFix: (prompt: string) => void; disabled: boolean }) {
  const [prompt, setPrompt] = useState("");
  const handleSubmit = () => {
    if (prompt.trim()) {
      onFix(prompt.trim());
      setPrompt("");
    }
  };
  return (
